from connect_policy import defer_mcp_join
from registry_policy import oneshot_skips_imported
from request_state import first_request_join

class Session:
    def __init__(self):
        self.already_skipped = [False]

    def request(self, pending, yolo, json_mode, oneshot, lean, project_servers):
        include_imported = not oneshot_skips_imported(oneshot, lean, project_servers)
        if not pending:
            action = "none"
        elif defer_mcp_join(yolo, json_mode):
            action = first_request_join(pending, self.already_skipped)
        else:
            action = "join"
        return {"action": action, "include_imported": include_imported}

